import { createTheme } from '@mui/material/styles';

const theme = createTheme({
    typography: {
        fontFamily: 'Inter, Roboto, sans-serif',
        fontSize: 16,
        fontWeightRegular: 400,
        fontWeightMedium: 500,
        h1: { fontSize: '2rem', fontWeight: 600 },
        h2: { fontSize: '1.6rem', fontWeight: 600 },
        h3: { fontSize: '1.3rem', fontWeight: 500 },
        body1: { fontSize: '1rem' },
    },

    palette: {
        mode: 'light',
        background: {
            default: '#f9fafb', // fondo general claro
            paper: '#ffffff',   // tarjetas / tablas
        },
        primary: {
            main: '#2563eb',
        },
        text: {
            primary: '#111827',
            secondary: '#6b7280',
        },
    },

    components: {
        MuiCssBaseline: {
            styleOverrides: {
                body: {
                    fontFamily: 'Inter, Roboto, sans-serif',
                    WebkitFontSmoothing: 'antialiased',
                    MozOsxFontSmoothing: 'grayscale',
                },
            },
        },

        MuiDataGrid: {
            styleOverrides: {
                root: {
                    backgroundColor: '#ffffff',
                    fontSize: 18, // tamaño de letra general en DataGrid
                },
                columnHeaders: {
                    backgroundColor: '#f3f4f6',
                    fontSize: 18,
                    fontWeight: 600,
                },
                cell: {
                    fontFamily: 'JetBrains Mono, monospace',
                    fontVariantNumeric: 'tabular-nums',
                    fontSize: 30, // tamaño de las celdas
                },
                footerContainer: {
                    fontSize: 16,
                },
            },
        },

        MuiTableCell: {
            styleOverrides: {
                root: {
                    fontSize: 15,
                },
                head: {
                    fontWeight: 600,
                },
            },
        },

        MuiButton: {
            styleOverrides: {
                root: {
                    fontSize: 14,
                    textTransform: 'none',
                    fontWeight: 500,
                },
            },
        },
    },
});

export default theme;