import React, { useContext, useState } from 'react'
import { GeneralCtx } from "../../contextos/GeneralContext";
import { useQuery } from '@tanstack/react-query'
import {
    AppBar,
    Grid,
    Toolbar,
    Typography,
    Tooltip,
    IconButton,
    TextField,
    Button,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Box
} from '@mui/material'
import { ArrowBack as ArrowBackIcon, ArrowForward as ArrowForwardIcon } from "@mui/icons-material";
import { LocalizationProvider, DesktopDatePicker } from "@mui/x-date-pickers";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { LeerPedidos, LeerPedidosObserva, PutPedidosObserva, PutPedidosFinalizado } from '../../servicios/Pedidos'
//
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo'
import { DataGrid, GRID_DEFAULT_LOCALE_TEXT } from '@mui/x-data-grid';
import dayjs from "dayjs";
import 'dayjs/locale/es';




export default function PedidosPagina() {
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    const [pedidos, setPedidos] = useState([])
    //menejo de fechas
    const [date, setDate] = useState(dayjs());
    //
    const [openDialog, setOpenDialog] = useState(false);
    const [filaSeleccionada, setFilaSeleccionada] = useState(null);
    //
    const { getSession } = useContext(GeneralCtx);

    const session = getSession();
    //
    const usuario = session?.usuario;
    let mensAriagroPedidos = usuario.mensAriagroPedidos || 0;
    const columnaUsuario = `usu${usuario.mensAriagroPedidos || 0}`;
    console.log(usuario);


    const handleChange = (e) => {
        setDate(dayjs(e.target.value));
    };

    const queryPedidos = useQuery({
        queryKey: ['pedidos', date.format("YYYY-MM-DD")], // la fecha entra como dependencia
        queryFn: async () => {
            try {
                // Pasamos la fecha seleccionada a LeerPedidos
                const data = await LeerPedidos(
                    date.format("YYYY-MM-DD"),
                    mensAriagroPedidos
                );

                if (data) {
                    const pedidosLimpios = formatearPedidos(data); // limpia campos nulos

                    setPedidos(pedidosLimpios);

                    return pedidosLimpios;
                }

                // importante: devolver algo si no hay data
                return [];
            } catch (error) {
                console.error('Error en queryFn:', error);
                setMensajeError(MensajeError(error));
                setHayError(true);
                throw error; // necesario para que React Query registre el error
            }
        },
        refetchInterval: 2 * 60 * 1000, // se actualiza cada 2 minutos automáticamente
        refetchOnWindowFocus: true,
        refetchIntervalInBackground: true, // 👈 añadido para que también refresque en background
    });

    const queryObservaciones = useQuery({
        queryKey: ['observaciones', filaSeleccionada?.numpedid, filaSeleccionada?.numlinea],
        queryFn: async () => {
            try {
                let data = await LeerPedidosObserva(filaSeleccionada.numpedid, filaSeleccionada.numlinea);
                return data;
            } catch (error) {
                console.error('Error en queryFn:', error);
                setMensajeError(MensajeError(error));
                setHayError(true);
                throw error; // necesario para que React Query registre el error
            }

        },
        enabled: openDialog && !!filaSeleccionada // ✅ solo ejecuta al abrir modal
    });

    // Transformamos y ordenamos observaciones
    const observacionesTransformadas = queryObservaciones.data?.map(obs => {
        const columnaUsuario = `usu${usuario.mensAriagroPedidos || 0}`;
        const leido = obs[columnaUsuario] === 1;
        return {
            ...obs,
            leido,
            leidoTexto: leido ? "SI" : "NO",
        };
    })
        .sort((a, b) => {
            // Primero las no leídas
            if (a.leido !== b.leido) return a.leido ? 1 : -1;

            // Luego ordenar por fecha descendente (más reciente primero)
            const fechaA = new Date(a.fechahora);
            const fechaB = new Date(b.fechahora);
            return fechaB - fechaA;
        });

    const hayNoLeidas = observacionesTransformadas?.some(obs => !obs.leido);



    const marcarTodasComoLeidas = async () => {
        if (!filaSeleccionada) return;

        const numpedid = filaSeleccionada.numpedid;
        const numlinea = filaSeleccionada.numlinea;
        console.log("Marcar observaciones como leídas:", numpedid);
        try {
            const data = await PutPedidosObserva(numpedid, numlinea, mensAriagroPedidos);
            if (data) {
                setMensaje('Observaciones marcadas como leídas');
                setHayMensaje(true);
                setOpenDialog(false);
                queryPedidos.refetch();
            }

        } catch (error) {
            console.error('Error al marcar como leído:', error);
            setMensajeError(MensajeError(error));
            setHayError(true);
        }
    };

    const marcarComoFinalizado = async () => {
        if (!filaSeleccionada) return;

        const numpedid = filaSeleccionada.numpedid;
        const numlinea = filaSeleccionada.numlinea;
        let d = { finalizado: 1 }
        try {
            const data = await PutPedidosFinalizado(numpedid, numlinea, d);
            setMensaje('Pedido marcado como finalizado');
            setHayMensaje(true);
            setOpenDialog(false);
            queryPedidos.refetch(); // refresca el grid
        } catch (error) {
            console.error('Error al marcar como finalizado:', error);
            setMensajeError(MensajeError(error));
            setHayError(true);
        }
    };

    const localeTextES = {
        noRowsLabel: 'No hay datos',
        noResultsOverlayLabel: 'No se encontraron resultados',
        errorOverlayDefaultLabel: 'Ha ocurrido un error.',
        footerRowSelected: (count) =>
            count !== 1
                ? `${count.toLocaleString()} filas seleccionadas`
                : `${count.toLocaleString()} fila seleccionada`,
        footerTotalRows: 'Total de filas:',
        MuiTablePagination: {
            labelRowsPerPage: 'Filas por página:',
            labelDisplayedRows: ({ from, to, count }) =>
                `${from}–${to} de ${count !== -1 ? count : `más de ${to}`}`,
        },
    };
    const totalRow = {
        id: 'total', // id único para la fila de totales
        kgs: pedidos.reduce((sum, row) => sum + (row.kgs || 0), 0),
        totpalet: pedidos.reduce((sum, row) => sum + (row.totpalet || 0), 0),
        numcajas: pedidos.reduce((sum, row) => sum + (row.numcajas || 0), 0)
    };


    const rowsWithTotal = [...pedidos];




    const formatearPedidos = (pedidos) => {
        return pedidos.map(p => ({
            codigo: p.codigo || '',
            codpalet: p.codpalet ?? 0,
            codtrans: p.codtrans ?? 0,
            codvarie: p.codvarie ?? 0,
            confeccion: p.confeccion || '',
            horacarga: p.horacarga || '',
            kgs: p.kgs ?? 0,
            kiloscaj: p.kiloscaj ?? 0,
            matrirem: p.matrirem || '',
            matriveh: p.matriveh || '',
            nomcalib: p.nomcalib || '',
            nomclien: p.nomclien || '',
            nompalet: p.nompalet || '',
            nomtrans: p.nomtrans || '',
            nomvarie: p.nomvarie || '',
            numcajas: p.numcajas ?? 0,
            numpedid: p.numpedid ?? 0,
            numlinea: p.numlinea ?? 0,
            refclien: p.refclien || '',
            teltrans: p.teltrans || '',
            totpalet: p.totpalet ?? 0,
            numalbar: p.numalbar || '',
            estadopalet: p.estadopalet,
            hay_nueva: p.hay_nueva || 0,
            finalizado: p.finalizado || 0
        }));
    };

    const handleRowDoubleClick = (params) => {
        setFilaSeleccionada(params.row);
        setOpenDialog(true);
    };


    const columns = [
        {
            field: 'kgs',
            headerName: 'kgs',
            width: 70,
            align: 'right',
            headerAlign: 'right',
            cellClassName: 'bold-cell',
            headerClassName: 'bold-header',
        },

        { field: 'codigo', headerName: 'Pedido', width: 100 },

        // 👇 Reducido bastante
        { field: 'nomclien', headerName: 'Cliente', flex: 0.8 },

        {
            field: 'totpalet',
            headerName: 'Pal.',
            width: 65,
            align: 'right',
            headerAlign: 'right',
        },

        { field: 'nompalet', headerName: 'Nom.Palet', flex: 1 },

        {
            field: 'numcajas',
            headerName: 'Caj.',
            width: 55,
            align: 'right',
            headerAlign: 'right',
        },

        {
            field: 'kiloscaj',
            headerName: 'Kg/caj.',
            width: 75,
            align: 'right',
            headerAlign: 'right',
        },

        // 👇 Mucho más compacta
        { field: 'nomvarie', headerName: 'Var.', flex: 1 },

        // 👇 Sigue siendo la más importante visualmente
        { field: 'confeccion', headerName: 'Conf.', flex: 2 },

        { field: 'nomcalib', headerName: 'Cal.', width: 70 },

        {
            field: 'estadopalet',
            headerName: 'L',
            width: 45,
            valueFormatter: (param) => {
                if (param === 1) return 'NO';
                if (param === 2) return 'SI';
                return '';
            }
        }
    ];
    const columnasFormateadas = columns.map((col) => {
        const camposNumericos = ['kgs', 'totpalet', 'numcajas', 'kiloscaj'];

        if (camposNumericos.includes(col.field)) {
            return {
                ...col,
                renderCell: (params) => {
                    const valor = Number(params.value ?? 0); // aseguramos número
                    // formateo con separador de miles y 2 decimales
                    // ✅ Si es kiloscaj → 2 decimales
                    const opcionesFormato = col.field === 'kiloscaj'
                        ? { minimumFractionDigits: 2, maximumFractionDigits: 2 }
                        : { minimumFractionDigits: 0, maximumFractionDigits: 0 };

                    const valorFormateado = valor.toLocaleString('es-ES', opcionesFormato);
                    // Regex para forzar punto como separador de miles
                    const valorSeguro = valorFormateado.replace(/\B(?=(\d{3})+(?!\d))/g, ".");

                    return params.row.id === 'total'
                        ? <strong>{valorSeguro}</strong>
                        : valorSeguro;
                },
                headerAlign: 'right',
                align: 'right',
            };
        }

        return col;
    });

    return (
        <>
            <MenuLateral>
                <Grid container

                    justifyContent="center"
                    alignItems="center"
                    sx={{
                        minHeight: '85vh', // altura completa
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#FFFF',

                    }}>

                    <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="es">
                        <AppBar id="imagen" position="static" color="secondary">
                            <Toolbar sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                                <Typography variant='h6'>
                                    Fecha carga: {date.locale('es').format('dddd D [de] MMMM [de] YYYY')}
                                </Typography>
                                <Typography variant='h6'>
                                    Total kilos: {totalRow.kgs.toLocaleString('es-ES')}
                                </Typography>
                                <Typography variant='h6' sx={{ flexGrow: 1 }}>
                                    Total cajas: {totalRow.numcajas.toLocaleString('es-ES')}
                                </Typography>

                                <Tooltip title="Día anterior">
                                    <IconButton color="inherit" onClick={() => setDate(date.subtract(1, "day"))}>
                                        <ArrowBackIcon />
                                    </IconButton>
                                </Tooltip>

                                {/* DesktopDatePicker */}
                                <DesktopDatePicker
                                    inputFormat="YYYY-MM-DD"
                                    value={date}
                                    onChange={(newDate) => {
                                        if (newDate && dayjs(newDate).isValid()) setDate(dayjs(newDate));
                                    }}
                                    sx={{
                                        bgcolor: "white",
                                        borderRadius: 1,
                                        input: { fontSize: 17 },
                                        width: 160,
                                        height: 50,
                                    }}
                                />

                                <Tooltip title="Día siguiente">
                                    <IconButton color="inherit" onClick={() => setDate(date.add(1, "day"))}>
                                        <ArrowForwardIcon />
                                    </IconButton>
                                </Tooltip>
                            </Toolbar>
                            <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', ml: 2 }}>

                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    <Box sx={{ width: 14, height: 14, backgroundColor: '#e03b3b', borderRadius: 1 }} />
                                    <Typography variant="caption">Pendiente de leer</Typography>
                                </Box>

                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    <Box sx={{ width: 14, height: 14, backgroundColor: '#948ddb', borderRadius: 1 }} />
                                    <Typography variant="caption">Nuevo</Typography>
                                </Box>

                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                    <Box sx={{ width: 14, height: 14, backgroundColor: '#296b2f', borderRadius: 1 }} />
                                    <Typography variant="caption">Finalizado</Typography>
                                </Box>

                            </Box>
                        </AppBar>
                    </LocalizationProvider>

                    <Grid item xs={12} sx={{ height: '75vh', width: '100%', overflow: 'hidden' }}>
                        
                        <DataGrid
                            rows={rowsWithTotal}
                            columns={columnasFormateadas}
                            getRowId={(row) => row.id ?? row.codigo}
                            localeText={localeTextES}
                            onRowDoubleClick={handleRowDoubleClick}
                            rowHeight={30} // ↑ aumenta la altura de fila para que la letra grande se vea
                            headerHeight={60} // ↑ altura de cabecera mayor

                            getRowClassName={(params) => {
                                let clases = [];

                                if (params.row.id === 'total') clases.push('MuiDataGrid-row--total');
                                if (params.row.finalizado === 1) clases.push('fila-verde');
                                if (params.row.estadopalet === 1 && params.row.hay_nueva == 0) clases.push('fila-roja');
                                if (params.row.estadopalet === 1 && params.row.hay_nueva === 1) clases.push('fila-azul');
                                if (params.row.estadopalet === 2) clases.push('fila-amarilla');

                                return clases.join(' ');
                            }}
                            sx={{
                                borderRadius: 2,
                                boxShadow: 10,
                                border: 'none',
                                fontFamily: 'JetBrains Mono, monospace',
                                height: '100%',
                                '.MuiDataGrid-virtualScroller': {
                                    overflowY: 'auto !important',
                                    overflowX: 'auto !important',
                                },
                                '.MuiDataGrid-columnHeaders': {
                                    color: '#1723d4 !important',
                                    fontSize: 20, // ↑ cabecera más grande
                                    fontWeight: '900',
                                    borderBottom: '3px solid #90caf9',
                                },
                                '.MuiDataGrid-cell': {
                                    fontSize: 15, // ↑ letra más grande visible
                                    color: '#333',
                                },
                                '.MuiDataGrid-row': {
                                    backgroundColor: '#f9f9f9',
                                    '&:nth-of-type(even)': {
                                        backgroundColor: '#e3f2fd',
                                    },
                                },
                                '.MuiDataGrid-row:hover': {
                                    backgroundColor: '#bbdefb',
                                },
                                '.MuiDataGrid-row.Mui-selected': {
                                    backgroundColor: '#90caf9 !important',
                                    color: '#fff',
                                },
                                '.MuiDataGrid-footerContainer': {
                                    display: 'none',
                                },
                                '.MuiDataGrid-toolbarContainer': {
                                    backgroundColor: '#e3f2fd',
                                    borderBottom: '1px solid #90caf9',
                                    borderRadius: '10px 10px 10px 10px',
                                },
                                '.bold-header': {
                                    fontWeight: '900',
                                    color: '#010107ff',
                                },
                                '.bold-cell': {
                                    fontWeight: 'bold',
                                    color: '#000',
                                },
                                '.MuiDataGrid-row--total': {
                                    fontWeight: 'bold',
                                    backgroundColor: '#e0e0e0',
                                },
                                '.MuiDataGrid-overlay': {
                                    color: '#fff',
                                    backgroundColor: 'transparent',
                                    fontSize: 18,
                                    fontWeight: 'bold',
                                },
                                '.fila-verde .MuiDataGrid-cell': {
                                    color: '#296b2fff !important',
                                    fontWeight: 'bold',
                                },
                                '.fila-verde.Mui-selected .MuiDataGrid-cell': {
                                    color: '#296b2fff !important',
                                },
                                '.fila-verde:hover .MuiDataGrid-cell': {
                                    color: '#296b2fff !important',
                                },
                                '.fila-roja .MuiDataGrid-cell': {
                                    background: '#d45959 !important',
                                    color: 'black !important',
                                    fontWeight: 'bold',
                                },
                                '.fila-roja': {
                                    cursor: 'pointer',
                                },
                                '.fila-azul .MuiDataGrid-cell': {
                                    background: '#948ddb !important',
                                    color: 'black !important',
                                    fontWeight: 'bold',
                                },
                                '.fila-azul': {
                                    cursor: 'pointer',
                                },
                                '.fila-amarilla': {
                                    cursor: 'pointer',
                                },
                            }}
                        />
                    </Grid>
                    {/* Aquí iría el Dialog para detalles del pedido */}
                    <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="md" fullWidth>

                        {/* 🔴 CABECERA CON COLOR POR ESTADO */}
                        <DialogTitle
                            sx={{
                                display: "flex",
                                justifyContent: "space-between",
                                alignItems: "center",
                                backgroundColor:
                                    filaSeleccionada?.estadopalet === 1 ? "#d45959" :
                                        filaSeleccionada?.estadopalet === 2 ? "#ffd54f" :
                                            "#e3f2fd",
                                color: "#000",
                                fontWeight: "bold"
                            }}
                        >
                            Observaciones pedido {filaSeleccionada?.numpedid}

                            <Box>
                                <Button variant="contained"
                                    color="primary"
                                    onClick={marcarComoFinalizado}
                                    disabled={filaSeleccionada?.finalizado === 1}
                                    sx={{ mr: 1 }}
                                >
                                    Marcar como finalizado
                                </Button>
                                <Button
                                    variant="contained"
                                    color="success"
                                    onClick={marcarTodasComoLeidas}
                                    disabled={!hayNoLeidas}
                                >
                                    Marcar como leído
                                </Button>
                            </Box>
                        </DialogTitle>

                        <DialogContent dividers sx={{ maxHeight: 500, overflowY: "auto" }}>

                            {/* 🧾 DATOS DEL PEDIDO */}
                            {filaSeleccionada && (
                                <>
                                    <Typography variant="h6" sx={{ mb: 1 }}>
                                        Datos del pedido
                                    </Typography>

                                    <Box
                                        sx={{
                                            display: "grid",
                                            gridTemplateColumns: "140px 1fr 140px 1fr",
                                            gap: 1,
                                            mb: 2,
                                            fontSize: 17,
                                            alignItems: "center",
                                            backgroundColor: "#f7f7f7",
                                            padding: 2,
                                            borderRadius: 2,
                                            border: "1px solid #ddd"
                                        }}
                                    >
                                        <b>Referencia:</b> <span>{filaSeleccionada.refclien}</span>
                                        <b>Hora carga:</b> <span>{filaSeleccionada.horacarga}</span>

                                        <b>Transportista:</b> <span>{filaSeleccionada.nomtrans}</span>
                                        <b>Teléfono:</b> <span>{filaSeleccionada.teltrans}</span>

                                        <b>Vehículo:</b> <span>{filaSeleccionada.matriveh}</span>
                                        <b>Remolque:</b> <span>{filaSeleccionada.matrirem}</span>
                                    </Box>
                                </>
                            )}

                            {/* 🔽 OBSERVACIONES (SIN CAMBIOS) */}
                            {queryObservaciones.isLoading && <Typography>Cargando observaciones...</Typography>}

                            {observacionesTransformadas?.length === 0 && <Typography>No hay observaciones</Typography>}

                            {observacionesTransformadas?.length > 0 && (
                                <Box
                                    sx={{
                                        display: "grid",
                                        gridTemplateColumns: "150px 150px 1fr 80px",
                                        gap: 1,
                                        fontSize: 18,
                                    }}
                                >
                                    {/* Cabecera */}
                                    <Typography fontWeight="bold">Usuario</Typography>
                                    <Typography fontWeight="bold">Fecha</Typography>
                                    <Typography fontWeight="bold">Observación</Typography>
                                    <Typography fontWeight="bold" textAlign="center">Leído</Typography>

                                    {/* Filas */}
                                    {observacionesTransformadas.map(obs => (
                                        <React.Fragment key={obs.idUnicoObserva}>
                                            <Typography
                                                sx={{
                                                    whiteSpace: "normal",
                                                    wordBreak: "break-word",
                                                    backgroundColor: obs.leido ? "#e6f4ea" : "#fce8e6",
                                                    padding: 1,
                                                    borderRadius: 1,
                                                }}
                                            >
                                                {obs.usuCreacion}
                                            </Typography>
                                            <Typography
                                                sx={{
                                                    whiteSpace: "normal",
                                                    backgroundColor: obs.leido ? "#e6f4ea" : "#fce8e6",
                                                    padding: 1,
                                                    borderRadius: 1,
                                                }}
                                            >
                                                {dayjs(obs.fechahora).format("DD/MM/YYYY HH:mm")}
                                            </Typography>
                                            <Typography
                                                sx={{
                                                    whiteSpace: "pre-line",
                                                    backgroundColor: obs.leido ? "#e6f4ea" : "#fce8e6",
                                                    padding: 1,
                                                    borderRadius: 1,
                                                }}
                                            >
                                                {obs.observaciones}
                                            </Typography>
                                            <Typography
                                                sx={{
                                                    fontWeight: "bold",
                                                    color: obs.leido ? "green" : "red",
                                                    textAlign: "center",
                                                    backgroundColor: obs.leido ? "#e6f4ea" : "#fce8e6",
                                                    padding: 1,
                                                    borderRadius: 1,
                                                }}
                                            >
                                                {obs.leidoTexto}
                                            </Typography>
                                        </React.Fragment>
                                    ))}
                                </Box>
                            )}

                        </DialogContent>

                        <DialogActions>
                            <Button onClick={() => setOpenDialog(false)} variant="outlined">
                                Cerrar
                            </Button>
                        </DialogActions>

                    </Dialog>
                </Grid>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
            </MenuLateral>
        </>

    )
}
