import React, { useContext, useEffect, useState } from 'react';
import {
    Box,
    Drawer,
    AppBar,
    CssBaseline,
    Toolbar,
    List,
    ListItem,
    ListItemButton,
    ListItemIcon,
    IconButton,
    Tooltip,
    Typography,
    Collapse
} from '@mui/material';
import {
    Home,
    ExitToApp,
    Person,
    BarChart,
    LocalShipping,
    ReceiptLong,
    Menu as MenuIcon
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { GeneralCtx } from '../../contextos/GeneralContext';
import { leerVersion, leerEntorno } from '../../servicios/ApiLib';
import { TipoPantalla } from '../../utilidades/ControlPantalla';

const drawerWidth = 60;

export const MenuLateral = ({ children }) => {
    const navigate = useNavigate();
    const { getSession, deleteSession } = useContext(GeneralCtx);

    const [sesion, setSesion] = useState();
    const [version, setVersion] = useState('0.0.0');
    const [entorno, setEntorno] = useState({});
    const [drOpen, setDrOpen] = useState(false);
    const [tipoPantalla, setTipoPantalla] = useState('desktop');
    const [openMenu, setOpenMenu] = useState(true);

    useEffect(() => {
        const session = getSession();
        if (!session) navigate('/');
        setSesion(session);

        const init = async () => {
            const { data } = await leerVersion();
            setVersion(data.version);
            const entornoRes = await leerEntorno();
            setEntorno(entornoRes.data);
            setTipoPantalla(TipoPantalla());
        };
        init();
    }, []);

    const handleLogout = () => {
        deleteSession();
        navigate('/');
    };

    const MenuItem = ({ icon, label, onClick }) => (
        <Tooltip title={label} placement="right">
            <ListItem disablePadding sx={{ justifyContent: 'center' }}>
                <ListItemButton onClick={onClick}>
                    <ListItemIcon sx={{ minWidth: 'unset' }}>
                        {icon}
                    </ListItemIcon>
                </ListItemButton>
            </ListItem>
        </Tooltip>
    );

    /** Sub-item con líneas tipo árbol */
    const TreeItem = ({ icon, label, onClick, isLast }) => (
        <Tooltip title={label} placement="right">
            <ListItem disablePadding>
                <ListItemButton
                    onClick={onClick}
                    sx={{ pl: 4, position: 'relative' }}
                >
                    {/* Línea vertical */}
                    <Box
                        sx={{
                            position: 'absolute',
                            left: 16,
                            top: 0,
                            bottom: isLast ? '50%' : 0,
                            width: '2px',
                            bgcolor: 'rgba(0,0,0,0.3)',
                        }}
                    />
                    {/* Línea horizontal */}
                    <Box
                        sx={{
                            position: 'absolute',
                            left: 16,
                            top: '50%',
                            width: 20,
                            height: '2px',
                            bgcolor: 'rgba(0,0,0,0.3)',
                        }}
                    />
                    <ListItemIcon sx={{ minWidth: 30 }}>
                        {icon}
                    </ListItemIcon>
                </ListItemButton>
            </ListItem>
        </Tooltip>
    );

    return (
        <Box sx={{ display: 'flex' }}>
            <CssBaseline />

            {/* AppBar */}
            <AppBar position="fixed" sx={{ zIndex: t => t.zIndex.drawer + 1 }}>
                <Toolbar>
                    {tipoPantalla === 'mobile' && (
                        <IconButton color="inherit" onClick={() => setDrOpen(!drOpen)}>
                            <MenuIcon />
                        </IconButton>
                    )}
                    <Typography sx={{ flexGrow: 1 }}>
                        AriAgroWeb VRS: {version}
                    </Typography>
                    <IconButton color="inherit">
                        <Person />
                        <Typography ml={1}>{sesion?.usuario?.nomusu}</Typography>
                    </IconButton>
                    <IconButton color="inherit" onClick={handleLogout}>
                        <ExitToApp />
                    </IconButton>
                </Toolbar>
            </AppBar>

            {/* Drawer */}
            <Drawer
                variant={tipoPantalla === 'mobile' ? 'temporary' : 'permanent'}
                open={tipoPantalla === 'mobile' ? drOpen : true}
                onClose={() => setDrOpen(false)}
                sx={{
                    width: drawerWidth,
                    '& .MuiDrawer-paper': {
                        width: drawerWidth,
                        overflowX: 'hidden'
                    }
                }}
            >
                <Toolbar />
                <List>

                    <MenuItem
                        icon={<Home fontSize="large" />}
                        label="Inicio"
                        onClick={() => navigate('/inicio')}
                    />

                    {/* Grupo */}
                    <MenuItem
                        icon={<BarChart fontSize="large" />}
                        label="Operaciones"
                        onClick={() => setOpenMenu(!openMenu)}
                    />

                    <Collapse in={openMenu}>
                        <List disablePadding>

                            {entorno.araw_pedidos !== '0' && (
                                <TreeItem
                                    icon={<LocalShipping fontSize="small" />}
                                    label="Pedidos"
                                    onClick={() => navigate('/pedidos')}
                                    isLast={entorno.araw_comparativa === '0'}
                                />
                            )}

                            {entorno.araw_comparativa !== '0' && (
                                <TreeItem
                                    icon={<ReceiptLong fontSize="small" />}
                                    label="Comparativa de ventas"
                                    onClick={() => navigate(`/comparativa/?reload=${Date.now()}`)}
                                    isLast
                                />
                            )}

                        </List>
                    </Collapse>

                </List>
            </Drawer>

            {/* Contenido */}
            <Box
                component="main"
                sx={{
                    flexGrow: 1,
                    ml: '10px',
                    mt: '84px',
                   ml: tipoPantalla === 'mobile' ? 0 : '5px'
                }}
            >
                {children}
            </Box>
        </Box>
    );
};
