import axios from 'axios'
import Entorno from './Entorno'

export const LeerPedidos = async (fecha, mensAriagroPedidos) => {
  const ent = Entorno.gentEnv();
  const url = `${ent.API_URL}/api/pedidos/porfecha/${fecha}/${mensAriagroPedidos}`;
  const response = await axios.get(url);
  if(response.data) return response.data; 
};

export const LeerPedidosObserva = async (numpedid, numlinea) => {
  const ent = Entorno.gentEnv();
  const url = `${ent.API_URL}/api/pedidos/observaciones/${numpedid}/${numlinea}`;
  const response = await axios.get(url);
  if(response.data) {
    console.log('Observaciones:', response.data);
    return response.data; 
  }
};

export const PutPedidosObserva = async (numpedid, numlinea, mensAriagroPedidos) => {
  const ent = Entorno.gentEnv();
  const url = `${ent.API_URL}/api/pedidos/observaciones/${numpedid}/${numlinea}/${mensAriagroPedidos}`;
  const response = await axios.put(url);
  if(response.data) {
    return response.data; 
  }
};

export const PutPedidosFinalizado = async (numpedid, numlinea, datos) => {
  const ent = Entorno.gentEnv();
  const url = `${ent.API_URL}/api/pedidos/${numpedid}/${numlinea}`;
  const response = await axios.put(url, {data: datos});
  if(response.data) {
    return response.data; 
  }
};